/**
 * The v2.2 open limits a ticket must quote (percolator-prog feat/v22-rc23-2026-10-22 @ 02524b05):
 *  - the rc23 κ cap (#594) and λ cap (#599) on the growth dials (growthCeilingView / quoteMaxLeverage);
 *  - the leverage guard's open rules (lev_guard_v22.rs + lev_trade_post).
 *
 * Parity: fixtures/v22/lev-guard-limits-parity-02524b05.json was generated by compiling the program's OWN pure functions
 * (lev_guard_v22.rs lines 18-466 / 669-700 and growth_v19.rs kappa_*, sigma_h_bps, isqrt_ceil_u128, n_cap_q, ceiling_imr_bps,
 * copied verbatim from 02524b05) in a scratch crate with seeded random inputs. Every case must match exactly.
 */
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { PublicKey } from "@solana/web3.js";
import {
  ASSET_GROWTH_LEN, DEPTH_EVER, DEPTH_PREV_REAL, DEPTH_SOURCE, STRESS_NONE, decodeAssetGrowthRecordV19, growthCeilingView, quoteMaxLeverage,
  kappaEffBps, lambdaFallbackBps, sigmaHBps, LAMBDA_VOL_HORIZON_SLOTS,
  levLTraderX100V22, levLOverlayX100V22, levNOverlayQV22, levShortUsersCapNotionalV22, levMergeOverlayV22, levBurstDecayV22,
  levBurstUpdateV22, levBurstVarEffV22, levObservePriceV22, levAgeBandV22, levGuardOpenLimitsV22, levGuardMaxFillQV22,
  levGuardMaxPositionQV22, levGuardRefusalV22, levGuardLeverageOkV22,
} from "../src/index.js";
import type { LevAgeBandV22, LevGuardV22, LevGuardOpenInputV22 } from "../src/index.js";

const V = JSON.parse(readFileSync(join(__dirname, "..", "fixtures", "v22", "lev-guard-limits-parity-02524b05.json"), "utf8"));
const n = (x: number | string | null): bigint | null => (x === null ? null : BigInt(x));

describe("parity with the program's own functions (02524b05)", () => {
  it("l_trader_x100", () => {
    for (const [mmr, s, j, want] of V.lTrader) expect(levLTraderX100V22(BigInt(mmr), n(s), j)).toBe(want);
  });
  it("l_overlay_x100", () => {
    for (const [e, lt, lc, mo, fz, le, want] of V.lOverlay) expect(levLOverlayX100V22(e, lt, lc, mo, fz, le)).toBe(want);
  });
  it("n_overlay_q", () => {
    for (const [nc, band, m, f, fz, want] of V.nOverlay) expect(levNOverlayQV22(BigInt(nc), band as LevAgeBandV22, m, BigInt(f), n(fz))).toBe(BigInt(want));
  });
  it("short_users_cap_notional", () => {
    for (const [l, c, mmr, band, mi, want] of V.shortCap) expect(levShortUsersCapNotionalV22(BigInt(l), BigInt(c), BigInt(mmr), band as LevAgeBandV22, mi)).toBe(BigInt(want));
  });
  it("merge_overlay (report freshness, holder proof, mint / freeze authority)", () => {
    for (const [band, now, rj, rm, rl, rn, rs, ma, fa, hd, hs, oj, om, ol, on] of V.merge) {
      const g = { repJDumpBps: rj, repMIndBps: rm, repLCapX100: rl, repNMultBps: rn, repSlot: BigInt(rs), mintAuthLive: ma, freezeAuthLive: fa, holderDumpBps: hd, holderDumpSlot: BigInt(hs) };
      expect(levMergeOverlayV22(band, g, BigInt(now))).toEqual({ jDumpBps: oj, mIndBps: om, lCapX100: ol, nMultBps: on });
    }
  });
  it("burst memory", () => {
    for (const [p, ps, v, now, dec, np, ns, eff] of V.burst) {
      const elapsed = BigInt(now) > BigInt(ps) ? BigInt(now) - BigInt(ps) : 0n;
      expect(levBurstDecayV22(p, elapsed)).toBe(dec);
      expect(levBurstUpdateV22(p, BigInt(ps), v, BigInt(now))).toEqual([np, BigInt(ns)]);
      expect(levBurstVarEffV22(p, BigInt(ps), v, BigInt(now))).toBe(eff);
    }
  });
  it("observe_price (breaker / freeze / reference roll)", () => {
    for (const [lp, ls, rp, rs, fu, ou, px, now, s, , trip, nlp, nls, nrp, nrs, nfu, nou] of V.observe) {
      const r = levObservePriceV22({ lastPx: BigInt(lp), lastSlot: BigInt(ls), refPx: BigInt(rp), refSlot: BigInt(rs), freezeUntil: BigInt(fu), oracleUntil: BigInt(ou) }, BigInt(px), BigInt(now), n(s));
      expect(r.trip).toBe(trip);
      expect(r.band).toEqual({ lastPx: BigInt(nlp), lastSlot: BigInt(nls), refPx: BigInt(nrp), refSlot: BigInt(nrs), freezeUntil: BigInt(nfu), oracleUntil: BigInt(nou) });
    }
  });
  it("κ_eff and the λ cap", () => {
    for (const [kt, lam, v, wk, wl] of V.caps) {
      expect(kappaEffBps(kt, null)).toBe(wk);
      expect(lambdaFallbackBps(lam, sigmaHBps(v, LAMBDA_VOL_HORIZON_SLOTS))).toBe(wl);
    }
  });
  it("age_band", () => {
    for (const [t0, now, want] of V.ageBand) expect(levAgeBandV22(BigInt(t0), BigInt(now))).toBe(want);
  });
});

// ── rc23 caps on the growth quote ─────────────────────────────────────────────────────────────
const USD = 1_000_000n;
/** A tier-3 market (700k pool depth), no volatility data, LP equity 700k. */
function tier3Record() {
  const b = new Uint8Array(ASSET_GROWTH_LEN);
  const v = new DataView(b.buffer);
  v.setUint16(20, 500, true); v.setUint16(22, 2_000, true); v.setUint16(24, 2_000, true); v.setUint32(16, 30_000, true); v.setUint16(28, 3445, true);
  b[38] = 1; b[39] = 1; b[44] = DEPTH_EVER | DEPTH_PREV_REAL | DEPTH_SOURCE.OnChainPool;
  v.setBigUint64(56, 700_000n * USD, true); v.setBigUint64(64, 990n, true); v.setBigUint64(72, 700_000n * USD, true);
  v.setBigUint64(80, 700_000n * USD, true); v.setBigUint64(88, 990n, true);
  return decodeAssetGrowthRecordV19(b)!;
}

describe("rc23 κ / λ caps on the growth view (prog #594 / #599)", () => {
  const g = tier3Record();
  const cM = 700_000n * USD;
  const vol = { engineImrBps: 500n, liquidationFeeBps: 50n, bandMaxEpochSlots: 600n };
  it("κ_eff = min(κ, 253 bps) and λ_depth <= 1.0 on a clamp-enforced market; off with rc23Caps false", () => {
    const on = growthCeilingView(g, 1000, 1_000n, cM, STRESS_NONE, vol);
    const off = growthCeilingView(g, 1000, 1_000n, cM, STRESS_NONE, vol, { rc23Caps: false });
    expect(off.dials.kappaBps).toBeGreaterThan(253);
    expect(on.dials.kappaBps).toBe(253);
    expect(off.dials.lambdaDepthBps).toBeGreaterThan(10_000);
    expect(on.dials.lambdaDepthBps).toBeLessThanOrEqual(10_000);
    expect(on.lambdaEffBps).toBe(Math.min(g.lambdaBps, on.dials.lambdaDepthBps));
    expect(on.ceilingX100).toBe(off.ceilingX100); // leverage dial untouched
  });
  it("the quote's N_cap and room shrink (the κ depth cap binds: ~80x on this market)", () => {
    const input = (rc23Caps: boolean) => ({
      engineImrBps: 500n, growth: g, lpCapital: cM, lpPnl: 0n, lpFeeCredits: 0n, lpEffectivePositionQ: 0n, assetBound: true,
      oiEffLongQ: 0n, oiEffShortQ: 0n, priceE6: 1_000_000n, bankruptcyHlockActive: false,
      v22: { bandBps: 1000, nowSlot: 1_000n, vol: { liquidationFeeBps: 50n, bandMaxEpochSlots: 600n }, rc23Caps },
    });
    const on = quoteMaxLeverage(input(true), "long");
    const off = quoteMaxLeverage(input(false), "long");
    expect(on.nCapQ! < off.nCapQ!).toBe(true);
    // κ binds: depth 700k · 2.53% = 17,710 collateral => 17,710e6 Q at $1
    expect(on.nCapQ).toBe(17_710n * USD);
    expect(on.headroomQ).toBe(on.nCapQ);
    expect(on.lambdaEffBps).toBeLessThanOrEqual(10_000);
  });
  it("off the clamp (band 0): tier-0 dials, no caps (the program returns early)", () => {
    const v = growthCeilingView(g, 0, 1_000n, cM, STRESS_NONE, vol);
    expect(v.dials.kappaBps).toBe(5_000);
    expect(v.lambdaEffBps).toBe(g.lambdaBps);
  });
});

// ── the guard's open rules ────────────────────────────────────────────────────────────────────
const MARKET = new PublicKey(new Uint8Array(32).fill(9));
function guard(over: Partial<LevGuardV22> = {}): LevGuardV22 {
  return {
    market: MARKET, riskKey: PublicKey.default, t0Slot: 1_000_000n, assetIndex: 0, version: 1, bump: 255, flags: 0, mintAuthLive: false, freezeAuthLive: false,
    roundActive: false, roundLpLong: false, repJDumpBps: 0, repMIndBps: 0, repLCapX100: 0, repNMultBps: 0, repSlot: 0n, holderDumpBps: 0, roundKeepBps: 0,
    touchedN: 0, holderDumpSlot: 0n, pbLastPx: 0n, pbLastSlot: 0n, pbRefPx: 0n, pbRefSlot: 0n, pbFreezeUntil: 0n, pbOracleUntil: 0n, frozenLX100: 0, frozenNQ: 0n,
    navps: 0n, navLastEquity: 0n, navLastIn: 0n, navLastOut: 0n, navPeakCur: 0n, navPeakPrev: 0n, navRef: 0n, navBucketStart: 0n, navLastSlot: 0n, roundId: 0n,
    roundTargetQ: 0n, roundOpenSlot: 0n, burstVarPeakX100: 0, burstPeakSlot: 0n, touchedTags: [], ...over,
  };
}
const DAY = 216_000n;
function input(over: Partial<LevGuardOpenInputV22> = {}): LevGuardOpenInputV22 {
  return {
    guard: guard(), guardRequired: true, nowSlot: 1_000_000n + DAY / 2n, lNowX100: 500, nCapQ: 100_000n * USD, priceE6: 1_000_000n, targetPriceE6: 1_000_000n,
    volHasData: false, volVarX100: 0, mmrBps: 500n, engineImrBps: 1_000n, lTierX100: 2_000, collateralDecimals: 6, cM: 50_000n * USD,
    oiEffLongQ: 10_000n * USD, oiEffShortQ: 10_000n * USD, lpEffQ: -2_000n * USD, ...over,
  };
}

describe("levGuardOpenLimitsV22 (lev_trade_post)", () => {
  it("no guard required (devnet, bit clear): no rules", () => {
    const lim = levGuardOpenLimitsV22(input({ guardRequired: false }));
    expect(lim.applies).toBe(false);
    expect(levGuardMaxFillQV22(lim, input(), "long", 0n)).toBeNull();
  });
  it("required but absent: every open blocked (132), closes never", () => {
    const i = input({ guard: null });
    const lim = levGuardOpenLimitsV22(i);
    expect(lim.blocked).toBe("guard-missing");
    expect(levGuardRefusalV22(lim, i, 0n, 1n * USD, 1_000n * USD)).toBe("guard_required");
    expect(levGuardRefusalV22(lim, i, 5n * USD, -1n * USD, 1_000n * USD)).toBeNull(); // a reduce is not checked
  });
  it("under 6 h: blocked, opens at t0 + 54,000", () => {
    const i = input({ nowSlot: 1_000_000n + 10_000n });
    const lim = levGuardOpenLimitsV22(i);
    expect([lim.blocked, lim.opensAtSlot, lim.band]).toEqual(["age-under-6h", 1_054_000n, "NoOpen"]);
    expect(levGuardMaxFillQV22(lim, i, "long", 0n)).toBe(0n);
  });
  it("day 1: L_eff ~2.48x (MMR 5% + 0.3% + J 35%), below a 5x tier", () => {
    const lim = levGuardOpenLimitsV22(input());
    expect(lim.band).toBe("Day");
    expect(lim.lEffX100).toBe(248);
    expect(lim.imrBps).toBe(4_033n); // ceil(1e6 / 248)
  });
  it("week 1: ~3.95x; month+: the growth ceiling (no dump default)", () => {
    expect(levGuardOpenLimitsV22(input({ nowSlot: 1_000_000n + 2n * DAY })).lEffX100).toBe(395);
    expect(levGuardOpenLimitsV22(input({ nowSlot: 1_000_000n + 10n * DAY })).lEffX100).toBe(500);
  });
  it("a fresh holder report's l_cap binds; a live mint authority floors leverage at 2x and size at N_floor", () => {
    const now = 1_000_000n + 10n * DAY;
    expect(levGuardOpenLimitsV22(input({ nowSlot: now, guard: guard({ repLCapX100: 300, repSlot: now - 100n }) })).lEffX100).toBe(300);
    const mint = levGuardOpenLimitsV22(input({ nowSlot: now, guard: guard({ mintAuthLive: true }) }));
    expect(mint.lEffX100).toBe(200);
    expect(mint.nEffQ).toBe(200n * USD); // N_floor $200 at $1
  });
  it("the fill's own price sample trips the breaker (> 10%): m_oracle 3/4 in the same transaction", () => {
    // Day band: L_trader 2.48x; a breaker multiplies it by 3/4 (1.86x), lifted to the 2x floor.
    const now = 1_000_000n + DAY / 2n;
    const g = guard({ pbLastPx: 1_000_000n, pbLastSlot: now - 10n, pbRefPx: 1_000_000n, pbRefSlot: now - 10n });
    const calm = levGuardOpenLimitsV22(input({ nowSlot: now, guard: g, targetPriceE6: 1_050_000n }));
    expect([calm.frozen, calm.mOracle, calm.lEffX100]).toEqual([false, false, 248]);
    const lim = levGuardOpenLimitsV22(input({ nowSlot: now, guard: g, targetPriceE6: 1_200_000n }));
    expect([lim.frozen, lim.mOracle, lim.lEffX100]).toEqual([true, true, 200]);
  });
  it("size: the LP's net may grow only to n_eff (LP short 2,000: a long can add up to n_eff − 2,000 more)", () => {
    const i = input({ nowSlot: 1_000_000n + 10n * DAY, guard: guard({ repNMultBps: 1_000, repSlot: 1_000_000n + 10n * DAY - 1n }) });
    const lim = levGuardOpenLimitsV22(i);
    expect(lim.nEffQ).toBe(10_000n * USD); // 10% of N_cap 100k
    expect(levGuardMaxFillQV22(lim, i, "long", 0n)).toBe(8_000n * USD); // |−2000 − Δ| <= 10,000
    expect(levGuardMaxFillQV22(lim, i, "short", 0n)).toBe(12_000n * USD); // |−2000 + Δ| <= 10,000
    expect(levGuardRefusalV22(lim, i, 0n, 8_000n * USD, 10_000n * USD)).toBeNull();
    expect(levGuardRefusalV22(lim, i, 0n, 8_000n * USD + 1n, 10_000n * USD)).toBe("size");
  });
  it("a live W1 round: no fill may grow the LP", () => {
    const now = 1_000_000n + 10n * DAY;
    const i = input({ nowSlot: now, guard: guard({ roundActive: true, roundOpenSlot: now - 100n }) });
    const lim = levGuardOpenLimitsV22(i);
    expect(lim.roundLive).toBe(true);
    expect(levGuardMaxFillQV22(lim, i, "long", 0n)).toBe(0n); // LP short: a long grows it
    expect(levGuardRefusalV22(lim, i, 0n, 1n, 1_000n * USD)).toBe("lp_stop_round");
  });
  it("short cap under 7 d: users' shorts <= longs·MMR + 0.1·C_m (m = 100%)", () => {
    // users' long 10,000 (LP short, not on the long side); users' short 10,000 − 2,000 (LP leg) = 8,000.
    const i = input({ nowSlot: 1_000_000n + 2n * DAY, oiEffShortQ: 10_000n * USD });
    const lim = levGuardOpenLimitsV22(i);
    // cap = 10,000·5% + 50,000·10% = 500 + 5,000 = 5,500 < 8,000 already: no new short
    expect(levGuardMaxFillQV22(lim, i, "short", 0n)).toBe(0n);
    const roomy = input({ nowSlot: 1_000_000n + 2n * DAY, oiEffShortQ: 2_000n * USD }); // users' short 0
    const lim2 = levGuardOpenLimitsV22(roomy);
    expect(levGuardMaxFillQV22(lim2, roomy, "short", 0n)).toBe(5_500n * USD);
    expect(levGuardRefusalV22(lim2, roomy, 0n, -(5_500n * USD + 1n), 100_000n * USD)).toBe("short_dump_cap");
  });
  it("leverage: the largest position the equity carries at the guard's IMR", () => {
    const i = input();
    const lim = levGuardOpenLimitsV22(i);
    const maxQ = levGuardMaxPositionQV22(lim, 100n * USD, i.priceE6)!;
    expect(levGuardLeverageOkV22(lim, 100n * USD, maxQ, i.priceE6)).toBe(true);
    expect(levGuardLeverageOkV22(lim, 100n * USD, maxQ + 1n, i.priceE6)).toBe(false);
    expect(Number(maxQ) / 1e6).toBeCloseTo(100 * 2.48, 0);
  });
});
